<?php /** Shared salary-advance ledger block. Expects: $advances, $employee, $advanceMax. */ ?>
  <div class="panel"><h2><?= __('Advance Ledger') ?></h2>
    <p class="help"><?= __('Total outstanding across approved advances:') ?><strong><?= money(array_sum(array_map(fn($a) => max(0, (float)$a['amount'] - (float)$a['deducted']), $advances))) ?></strong></p>
    <?php if ($advanceMax > 0): ?><p class="help"><?= __('Maximum advance allowed for non-admin requesters:') ?><strong><?= money($advanceMax) ?></strong></p><?php endif; ?>
    <div class="table-wrap"><table class="tbl"><thead><tr><th><?= __('Date') ?></th><th class="num"><?= __('Amount') ?></th><th class="num"><?= __('Deducted') ?></th><th class="num"><?= __('Outstanding') ?></th><th><?= __('Notes') ?></th><th><?= __('Status') ?></th><th></th></tr></thead>
    <tbody><?php foreach ($advances as $a): $out = max(0, (float)$a['amount'] - (float)$a['deducted']); $canCancel = $a['status'] === 'pending' && ((int)($a['requested_by'] ?? 0) === (int)($_SESSION['user_id'] ?? 0) || is_owner_or_admin()); ?><tr><td><?= date_display($a['date']) ?></td><td class="num"><?= money($a['amount']) ?></td><td class="num"><?= money($a['deducted']) ?></td><td class="num"><?= money($out) ?></td><td><?= e($a['notes'] ?? '') ?></td><td><span class="badge <?= ['pending'=>'amber','approved'=>'blue','disbursed'=>'green','rejected'=>'red','cancelled'=>'gray'][$a['status']] ?? 'gray' ?>"><?= e(strtoupper($a['status'])) ?></span></td><td class="btn-group"><a class="btn btn-outline btn-sm" href="<?= e(url('employees/' . (int)$employee['id'] . '/advances/' . (int)$a['id'] . '/print')) ?>"><?= __('Print') ?></a><?php if ($canCancel): ?><form method="post" action="<?= e(url('employees/' . (int)$employee['id'] . '/advances/' . (int)$a['id'] . '/cancel')) ?>" style="display:inline" data-confirm="<?= __('Cancel this advance request?') ?>"><?= csrf_field() ?><button class="btn btn-danger btn-sm" type="submit"><?= __('Cancel Request') ?></button></form><?php endif; ?></td></tr><?php endforeach; ?>
    <?php if (!$advances): ?><tr><td colspan="6" class="muted"><?= __('No advances.') ?></td></tr><?php endif; ?></tbody></table></div>
    <p class="help"><?= __('Approved advances deduct automatically from the next salary run (capped so net cannot go negative). Loans use a separate ledger (Loans screen).') ?></p>
  </div>
